          items: { type: 'string', minLength: 1 },
          minItems: 1,
          maxItems: 5,
          uniqueItems: true,
          description: 'Array of 1-5 unique non-empty user id strings to look up.'
        }
      },
      required: ['user_ids'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'users_get_many') {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected a JSON object');
  }

  const providedKeys = Object.keys(args);
  if (providedKeys.length !== 1 || providedKeys[0] !== 'user_ids') {
    throw new Error("Invalid arguments: only 'user_ids' is permitted");
  }

  const { user_ids } = args;

  if (!Array.isArray(user_ids)) {
    throw new Error('Invalid arguments: user_ids must be an array of strings');
  }

  if (user_ids.length === 0) {
    throw new Error('Invalid arguments: user_ids must contain at least one entry');
  }

  if (user_ids.length > 5) {
    throw new Error('Invalid arguments: user_ids must contain at most 5 entries');
  }

  for (const id of user_ids) {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('Invalid arguments: every user_ids entry must be a non-empty string');
    }
  }

  if (new Set(user_ids).size !== user_ids.length) {
    throw new Error('Invalid arguments: user_ids entries must be unique');
  }

  const lines = user_ids.map((id) => {
    const record = users[id];
    if (record === undefined) {
      return `${id}: not found`;
    }
    return `${id}: ${record.name}`;
  });

  return {
    content: [{ type: 'text', text: lines.join('\n') }]
  };
}

